360	//    a time over all CTAs; the scratch holds X/A/AX/AAX/orth for the LARGEST 2D weight
361	//    + the per-CTA Frobenius-norm partials + inv_norm. The momentum buffer (muon_buf)
362	//    is NOT here — it PERSISTS across steps as optimizer state, bound to the m slice
363	//    (st.exp_avg). Largest decoder 2D weight: ff.0/ff.2 = 512×128 = 65536 numel; largest
364	//    rows = 512 ⇒ A = 512×512 (dectc::kDecMuonMaxNumel/kDecMuonMaxRows). Carved
365	//    UNCONDITIONALLY (≈ 4·65536 + 512² + nCTA + 1 floats ≈ 2 MB) so the opt-agnostic
366	//    launcher (dec_tc_launcher_scratch) fits every OptId; unused by every non-Muon cell
367	//    (its P2.7/P3-2D branches are if-constexpr'd out → byte-identical). ──
368	__host__ __device__ __forceinline__ int64_t dec_tc_muon_floats(int nCTA) {
369	    // X + AX + AAX + orth (each maxNumel) + A (maxRows²) + nrm_partials(nCTA) + inv_norm(1)
370	    return (int64_t)4 * dectc::kDecMuonMaxNumel
371	         + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows
372	         + nCTA + 1;
373	}
374	// ── LookSAM (STAGED in-kernel SAM 2nd backward) transient scratch. The SAM step
375	//    perturbs p in place, runs a SECOND fwd+bwd at p', and needs (a) a param BACKUP
376	//    for the exact restore (eager clones p before perturbing) + (b) a SEPARATE g_sam
377	//    grad buffer so the 2nd backward does NOT clobber the first grad `grad` (sam_dir
378	//    = g_sam − grad reads both). Both are total-sized + transient (NOT persistent
379	//    state — sam_dir itself persists in the `extra` state slice, bound by the cell).
380	//    Carved UNCONDITIONALLY (≈ 2·422755 ≈ 3.4 MB) so the opt-agnostic launcher fits
381	//    every OptId; unused by every non-LookSAM cell (its phase is if-constexpr'd out
382	//    → byte-identical). nrm_partials(nCTA)+inv_norm(1) for the ‖g‖ reduction reuse
383	//    the loss workspace (sq_part/coef_bc, as GrokAdamW's P2.5 does), so no extra here. ──
384	__host__ __device__ __forceinline__ int64_t dec_tc_looksam_floats() {
385	    return (int64_t)2 * kDecTotalElems;       // [sam_backup | sam_grad]
386	}
387	__host__ __device__ __forceinline__ int64_t dec_tc_workspace_floats(int T, int B, int nCTA) {
388	    return dec_tc_acts_floats(T, B)
389	         + (int64_t)nCTA * dectc::dec_tile_scratch_total_f32()
390	         + (int64_t)nCTA * dectc::kLnVecElems
391	         + nCTA + 1
392	         + dec_tc_dw_part_floats()            // split-K dW partials (G>1)
393	         + dec_tc_opt_reduce_floats(nCTA)     // STAGED-opt (Prodigy) reduce slots
394	         + dec_tc_muon_floats(nCTA)           // STAGED-opt (Muon) NS per-matrix scratch
395	         + dec_tc_looksam_floats();           // STAGED-opt (LookSAM) SAM 2nd-bwd scratch
396	}
397	
398	template <OptId Opt>
399	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
400	fused_decoder_megakernel_tc(PersistentContext ctx,
401	                            float* __restrict__ params,
402	                            DecoderTokenCtx tok,
403	                            float* __restrict__ grad,
404	                            float lr, int step, FusedOptState st) {
405	    __shared__ DecTcSmem sm;
406	    GridBarrier bar = ctx.barrier();
407	    const int cta = blockIdx.x;
408	    const int nCTA = (int)ctx.n_ctas;
409	    const int B = tok.B;
410	    const int T = B * dec::kSeq;
411	
412	    // Workspace partition.
413	    float* ws = tok.workspace;
414	    const int64_t acts_f = dec_tc_acts_floats(T, B);
415	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
416	    float* scratch_base = ws + acts_f;
417	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
418	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
419	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
420	    float* loss_out   = loss_part + nCTA;
421	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
422	    // loss slot (matches dec_tc_workspace_floats's term order). G==1 → dw_part unused.
423	    float* dw_part    = loss_out + 1;
424	    const int kDwG    = dectc::kDecDwSplitK;
425	    // STAGED-opt cross-CTA reduce slots (Prodigy d), carved AFTER the dW partials
426	    // (matches dec_tc_workspace_floats's term order). Unused unless Opt==Prodigy.
427	    float* opt_reduce = dw_part + dec_tc_dw_part_floats();
428	    // Muon NS per-matrix scratch, carved AFTER the Prodigy reduce slots (matches
429	    // dec_tc_workspace_floats's term order — carving it LAST keeps every prior
430	    // region's offset unchanged, so the 5 already-green cells are byte-identical).
431	    // Unused unless Opt==Muon. Layout (mirrors the vit twin):
432	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kDecMuonMaxNumel)
433	    //   [muon_A (kDecMuonMaxRows²)] [nrm_partials (nCTA)] [inv_norm (1)]
434	    float* muon_base = opt_reduce + dec_tc_opt_reduce_floats(nCTA);
435	    // LookSAM SAM 2nd-backward scratch, carved AFTER the Muon scratch (term order
436	    // matches dec_tc_workspace_floats — carving it LAST keeps every prior region's
437	    // offset unchanged, so the already-green cells are byte-identical). Layout:
438	    //   [sam_backup (total)] [sam_grad (total)]. Unused unless Opt==LookSAM.
439	    float* sam_backup = muon_base + dec_tc_muon_floats(nCTA);
440	    float* sam_grad   = sam_backup + kDecTotalElems;
441	
442	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
443	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
444	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
445	
446	    DecWeights w = dec_bind(params);
447	
448	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/embed grads are
449	    //    written-once → no pre-zero). ──

450	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
451	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
452	    bar.sync();   // B0
453	
454	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
455	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
456	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
457	    const int nrows_tile = dectc::kTileM;
458	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
459	    float nll_acc = 0.0f;
460	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
461	        const int g0 = ti * nrows_tile;
462	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
463	        float nll = dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
464	                                              sm.sA, sm.sB, sm.red);
465	        dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
466	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
467	        if (threadIdx.x == 0) nll_acc += nll;
468	        __syncthreads();
469	    }
470	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
471	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
472	
473	    // ── P2: assemble all 30 grads into `grad`. dW output-stationary (gt %
474	    //    nCTA), biases, embedding owner-scan, LN-vec reduce. No partials. The 9
475	    //    dW specs are built into SHARED smem (thread 0; identical for all) so the
476	    //    9-spec array is NOT on every thread's stack (shrinks the launch's local
477	    //    reservation — the persistent kernel must place on a memory-tight GPU). ──
478	    if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
479	    __syncthreads();
480	    dectc::DecDwSpec* spec = sm.spec;
481	    const int n_dw = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
482	    if (kDwG > 1) {
483	        // SPLIT-K (multi-CTA tiling): fan (n_dw·G) (tile,chunk) partials over the
484	        // grid so the ~62% idle SMs do work; deterministic ascending-chunk reduce.
485	        for (int item = cta; item < n_dw * kDwG; item += nCTA) {
486	            const int gt = item / kDwG, kc = item % kDwG;
487	            dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
488	        }
489	        bar.sync();   // all (gt,kc) partials complete before the reduce reads them
490	        dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec, n_dw, kDwG, dw_part, grad, cta, nCTA);
491	    } else {
492	        for (int gt = cta; gt < n_dw; gt += nCTA)
493	            dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
494	    }
495	    dectc::dectc_dw_biases(spec, grad);
496	    dectc::dectc_embed_owner_scan(acts, tok.tokens, T, grad, cta, nCTA);
497	    dectc::dectc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
498	    // Loss reduce (fp64) by CTA 0.
499	    if (cta == 0 && threadIdx.x == 0) {
500	        double s = 0.0;
501	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
502	        *tok.loss_out = (float)(s / (double)B);
503	    }
504	    (void)loss_out;
505	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
506	
507	    // ── P2.4 (LookSAM ONLY, SAM steps): the MODEL-COUPLED SAM 2nd backward that
508	    //    produces st.sam_dir = g_sam − g (INTEGRATION-OPTSTAGES §6). Eager LookSAM,
509	    //    every k steps (looksam.py sam_step + looksam.h:27-59):
510	    //      ‖g‖     = GLOBAL L2 norm over ALL reduced grads (compute_sam_grad_norm_
511	    //                device_side); rho_over_norm = rho/‖g‖
512	    //      p'      = p + rho_over_norm·g          (perturb in the grad direction;
513	    //                backup = p.clone() for the exact restore — fp32 add is not
514	    //                bit-reversible, so we MUST save, not subtract back)
515	    //      g_sam   = ∇L(p')                       (a FULL SECOND in-kernel fwd+bwd
516	    //                + deterministic grad assembly at the perturbed weights, written
517	    //                to the SEPARATE `sam_grad` buffer so `grad` (the first grad the
518	    //                apply tail blends from) is untouched)
519	    //      sam_dir = g_sam − g                    (cached in the PERSISTENT `extra`
520	    //                state slice == st.sam_dir; reused verbatim on the k−1 intervening
521	    //                steps where looksam_sam==0, so NO 2nd pass runs then)
522	    //      restore p = backup
523	    //    The apply tail (P3, apply_optimizer<LookSAM>) then blends g_adj=(1−α)g+α·
524	    //    sam_dir and runs AdamW — UNCHANGED. DETERMINISM: the ‖g‖ reduction is the
525	    //    IDENTICAL deterministic ascending-CTA shape as GrokAdamW's P2.5 (fixed
526	    //    contiguous per-CTA range → per-CTA partial → CTA0 ascending sum), and the
527	    //    2nd fwd+bwd+assembly reuses the SAME A/A/A-clean machinery as the first pass
528	    //    (fixed tile ownership, ascending-k reductions), so the whole phase is
529	    //    deterministic BY CONSTRUCTION. Guarded so every other opt's path is
530	    //    byte-identical (no extra barrier / work). On a NON-SAM step (looksam_sam==0)
531	    //    this whole block is skipped — st.sam_dir already holds the cached direction.
532	    if constexpr (Opt == OptId::LookSAM) {
533	        if (st.looksam_sam != 0.0f) {
534	            // (a) GLOBAL ‖g‖ over the reduced grad, deterministic (reuse the loss
535	            //     workspace as P2.5 does: loss_part[nCTA] = per-CTA Σg², loss_out[1]
536	            //     broadcasts rho_over_norm). The reduced loss is already in
537	            //     *tok.loss_out (host state), so this is free scratch.
538	            float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
539	            float* ron_bc  = loss_out;           // [1] broadcast rho_over_norm
540	            const int64_t total = kDecTotalElems;
541	            {
542	                const int64_t base = total / nCTA, rem = total % nCTA;
543	                const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
544	                const int64_t ecnt = base + (cta < rem ? 1 : 0);
545	                float tsum = 0.0f;
546	                for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
547	                    const float gv = grad[e0 + i];
548	                    tsum += gv * gv;
549	                }
550	                float* red = sm.red;
551	                red[threadIdx.x] = tsum;
552	                __syncthreads();
553	                for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
554	                    if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
555	                    __syncthreads();
556	                }
557	                if (threadIdx.x == 0) sq_part[cta] = red[0];
558	                bar.sync();   // B2.4a: all per-CTA Σg² partials complete
559	                if (cta == 0 && threadIdx.x == 0) {
560	                    double ss = 0.0;
561	                    for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
562	                    const float gnorm = sqrtf((float)ss);
563	                    // rho / ‖g‖ (matches bindings.cpp looksam_perturb_all). gnorm>0 in
564	                    // any real training step; guard div-by-0 → 0 (no perturb) to be safe.
565	                    *ron_bc = (gnorm > 0.0f) ? (st.rho / gnorm) : 0.0f;
566	                }
567	                bar.sync();   // B2.4b: rho_over_norm broadcast ready
568	            }
569	            const float rho_over_norm = *ron_bc;
570	            // (b) Backup + perturb p in place: p' = p + rho_over_norm·g. Grid-strided
571	            //     over the flat param vector (each element owned once → no race).
572	            {
573	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
574	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
575	                     i < total; i += gstride) {
576	                    sam_backup[i] = params[i];
577	                    params[i] = params[i] + rho_over_norm * grad[i];
578	                }
579	            }
580	            bar.sync();   // B2.4c: all params perturbed before the 2nd forward reads them
581	            // (c) SECOND fwd+bwd at the perturbed weights → g_sam in `sam_grad`. Mirror
582	            //     P1 + P2 EXACTLY, but: re-zero the lnvec partials (they accumulate),
583	            //     do NOT write the loss (keep the first-pass loss), and assemble into
584	            //     `sam_grad` (NOT `grad`). `w` wraps `params` (now perturbed) so the
585	            //     tile fns read the perturbed weights with no re-bind needed.
586	            for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
587	            bar.sync();   // B2.4d: lnvec partials cleared before the 2nd backward accumulates
588	            for (int ti = cta; ti < n_tiles; ti += nCTA) {
589	                const int g0 = ti * nrows_tile;
590	                const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
591	                dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
592	                                          sm.sA, sm.sB, sm.red);
593	                dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
594	                                           my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
595	                __syncthreads();
596	            }
597	            bar.sync();   // B2.4e: all 2nd-pass acts (X + dY) + LN-vec partials complete
598	            // Re-build the dW specs from the 2nd-pass acts (dY adjoints changed).
599	            if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
600	            __syncthreads();
601	            dectc::DecDwSpec* spec2 = sm.spec;
602	            const int n_dw2 = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec2);
603	            if (kDwG > 1) {
604	                for (int item = cta; item < n_dw2 * kDwG; item += nCTA) {
605	                    const int gt = item / kDwG, kc = item % kDwG;
606	                    dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec2, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
607	                }
608	                bar.sync();
609	                dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec2, n_dw2, kDwG, dw_part, sam_grad, cta, nCTA);
610	            } else {
611	                for (int gt = cta; gt < n_dw2; gt += nCTA)
612	                    dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec2, gt, sam_grad, sm.sA, sm.sB);
613	            }
614	            dectc::dectc_dw_biases(spec2, sam_grad);
615	            dectc::dectc_embed_owner_scan(acts, tok.tokens, T, sam_grad, cta, nCTA);
616	            dectc::dectc_lnvec_reduce(lnvec_base, sam_grad, nCTA, cta);
617	            bar.sync();   // B2.4f: g_sam fully assembled in sam_grad
618	            // (d) sam_dir = g_sam − g (into the persistent extra slice) + restore p.
619	            {
620	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
621	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
622	                     i < total; i += gstride) {
623	                    // st.sam_dir is the extra-slice base (host-bound). g_sam − g.
624	                    const_cast<float*>(st.sam_dir)[i] = sam_grad[i] - grad[i];
625	                    params[i] = sam_backup[i];   // restore the ORIGINAL weights
626	                }
627	            }
628	            bar.sync_reset(ctx.g_next_task);   // B2.4g: params restored + sam_dir ready; reset queue for P3
629	        }
630	    }
631	
632	    // ── P2.5 (GrokAdamW ONLY): GLOBAL grad-norm clip coefficient. Eager
633	    //    grokadamw clips the WHOLE grad set to grad_clip via a GLOBAL L2 norm
634	    //    (clip_grad_norms_device_side → total_norm = sqrt(Σ_i ‖g_i‖²),
635	    //    clip_coef = grad_clip/(total_norm+1e-6) when total_norm>grad_clip,
636	    //    else 1) BEFORE the apply. We replicate it on the REDUCED grad with a
637	    //    deterministic ascending reduction (no float atomics): each CTA sums a
638	    //    contiguous element-range into a per-CTA partial slot, CTA0 sums the
639	    //    partials in ascending CTA order → total_norm → clip_coef, broadcast via
640	    //    a workspace slot. The grad buffer is NOT mutated (the return_grad oracle
641	    //    + the eager-side clip must both see the unclipped reduced grad); the
642	    //    coefficient is applied per-element inside apply_optimizer<GrokAdamW>.
643	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
644	    if constexpr (Opt == OptId::GrokAdamW) {
645	        // Reuse the (now-consumed) loss workspace: loss_part[nCTA] holds per-CTA
646	        // partial sum-of-squares; loss_out (1 float) broadcasts clip_coef. The
647	        // reduced loss is already in *tok.loss_out (state), so this is free scratch.
648	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
649	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
650	        // Per-CTA contiguous element range over `grad` (the reduced grad, [total]).
651	        const int64_t total = kDecTotalElems;
652	        const int64_t base = total / nCTA, rem = total % nCTA;
653	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
654	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
655	        // Thread-local partial → block reduce (fixed tree) → thread0 writes the slot.
656	        float tsum = 0.0f;
657	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
658	            const float gv = grad[e0 + i];
659	            tsum += gv * gv;
660	        }
661	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
662	        float* red = sm.red;
663	        red[threadIdx.x] = tsum;
664	        __syncthreads();
665	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
666	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
667	            __syncthreads();
668	        }
669	        if (threadIdx.x == 0) sq_part[cta] = red[0];
670	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
671	        // CTA0 ascending-order reduce → total_norm → clip_coef (deterministic).
672	        if (cta == 0 && threadIdx.x == 0) {
673	            double ss = 0.0;
674	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
675	            const float total_norm = sqrtf((float)ss);
676	            float coef = 1.0f;
677	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
678	                coef = st.grad_clip / (total_norm + 1e-6f);
679	            *coef_bc = coef;
680	        }
681	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
682	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
683	    }
684	
685	    // ── P2.6 (PRODIGY ONLY): STAGED cross-ALL-tensors d-estimate. The apply tail
686	    //    (apply_optimizer<Prodigy>) reads st.d_factor (the effective LR scale d),
687	    //    a GLOBAL reduction over EVERY element of EVERY tensor. We compute it here,
688	    //    BYTE-FAITHFUL to the live eager multi-tensor path (prodigy_sm90.cuh:465-
689	    //    544, the order prodigy.py → _ops.prodigy_fused_step actually executes):
690	    //      d_prev  = persisted d_lr  (step 1: d0 cold-start — the zero-init state
691	    //                slot would give d_prev=0 ⇒ d=0 ⇒ frozen params; eager inits
692	    //                _d_lr=d0=1e-6, so seed it here, the grokfast-style step-1 fix)
693	    //      r_ema  <- beta3·r_ema + Σ d_prev²·<g, p0−p>     (decay persisted SCALAR,
694	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
695	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
696	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
697	    //
698	    //    DETERMINISM — FIXED-PARTITION reduction (mirrors the A/A/A-CLEAN GrokAdamW
699	    //    P2.5 grad-norm reduce above), NOT the work-steal task-queue drain. WHY THIS
700	    //    SHAPE: the previous form drained the global TaskQueue (q.next_block →
701	    //    atomicAdd(g_next_task)) inside phaseA and reset that SAME counter in a
702	    //    sync_RESET barrier (B2.6a). The work-steal claim order is timing-dependent,
703	    //    so each CTA's (r,s) slot holds a potentially DIFFERENT tensor subset run-to-
704	    //    run; because fp32 add is non-associative, the per-CTA partials then regroup
705	    //    the same values differently and the owner's d can differ at ULP level from
706	    //    step>=2 (a COMPONENT_CONTRACT deterministic-reduction violation — even where
707	    //    it happens to be empirically bit-exact on a given GPU/workload, it is not
708	    //    deterministic BY CONSTRUCTION). GrokAdamW's P2.5 reduces a FIXED contiguous
709	    //    element range per CTA with a plain sync() and is A/A/A-CLEAN; prodigy now
710	    //    uses the IDENTICAL shape — deterministic by construction, independent of CTA
711	    //    timing. Each CTA owns [e0,e0+ecnt) of the FLAT [0,total) arrays —
712	    //    params/param_init/grad are parallel flat blobs, so a contiguous flat range
713	    //    sum == the cross-all-TENSORS sum (tensor boundaries are irrelevant to a
714	    //    global Σ). The per-element contribution still CALLS the canonical
715	    //    prodigy_partials_step (prodigy.h:28-53, single-source). NO float atomic;
716	    //    per-CTA (r,s) slot publish → ONE plain grid barrier → CTA0 owner-sums
717	    //    ascending → EMA-decay/update_d → broadcast → ONE plain grid barrier.
718	    //    g_next_task is UNTOUCHED here (B2 already reset it to 0), so P3's queue
719	    //    drain runs unchanged — no sync_reset needed in P2.6.
720	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
721	    if constexpr (Opt == OptId::Prodigy) {
722	        // Per-CTA (r,s) slots in opt_reduce ([r slots | s slots]) + the reduced-d
723	        // broadcast slot. d_prev: persisted d_lr (slot 2), or d0 cold-start at step 1.
724	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
725	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
726	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
727	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
728	        // FIXED contiguous element range over the flat [0,total_p) arrays (same split
729	        // as GrokAdamW P2.5: even base + remainder to the low CTAs → deterministic).
730	        const int64_t total_p = kDecTotalElems;
731	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
732	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
733	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
734	        float r_acc = 0.0f, s_acc = 0.0f;
735	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
736	            // Canonical per-element partials (prodigy.h:28-53): r carries d²·<g,p0−p>,
737	            // s carries d²·|g| (the L1-norm denominator). params/param_init/grad are
738	            // flat blobs → index pe0+i is the same element in all three.
739	            algo::prodigy_partials_step(params, st.param_init, grad,
740	                                        d_prev, pe0 + i, r_acc, s_acc);
741	        }
742	        // Deterministic in-CTA two-value reduction (fixed thread count) → thread0
743	        // publishes this CTA's (r,s) slot. No atomic.
744	        float r_block, s_block;
745	        prim::block_reduce_sum2_f32(r_acc, s_acc, r_block, s_block);
746	        if (threadIdx.x == 0) { r_part[cta] = r_block; s_part[cta] = s_block; }
747	        bar.sync();   // B2.6a: all per-CTA (r,s) partials published & visible
748	        // Owner block (CTA0 thread0): ascending owner-sum + EMA decay + accumulate +
749	        // d_coef + update_d, byte-matching launch_multi_tensor_prodigy_fused_reduce_step.
750	        if (cta == 0 && threadIdx.x == 0) {
751	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
752	            for (int c = 0; c < nCTA; ++c) { r_step += r_part[c]; s_step += s_part[c]; }
753	            // Decay persisted scalars by beta3, then add this step's reduction.
754	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
755	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
756	            // d = max(d_prev, d_coef·r_ema/|s_ema|). prodigy_update_d does
757	            // max(d_prev, r/|s|) verbatim, so fold d_coef into the numerator copy
758	            // (persisted r_ema stays UNSCALED — returned/persisted, eager parity).
759	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
760	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
761	            st.prodigy_persist[1] = s_ema;
762	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
763	            d_bc[0]               = d_new;          // broadcast to all CTAs
764	        }
765	        bar.sync();   // B2.6b: d visible to every CTA before the apply
766	        st.d_factor = d_bc[0];                      // the reduced d the tail reads
767	    }
768	
769	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
770	    //    2D weights (INTEGRATION-OPTSTAGES §3). IDENTICAL to the vit twin
771	    //    (fused_vit_megakernel.cuh P2.7) — same shared opt_stages_precompute.cuh
772	    //    helpers, same barrier sequence — only the per-model 2D table (dectc::
773	    //    kDecMuon2D, 11 matrices including tok[99,128]/pos[4,128]) and offset array
774	    //    (kDecOffsets) differ. For EACH 2D matrix all CTAs cooperate: buf=μ·buf+g
775	    //    (buf is the PERSISTENT m-slice — momentum state, NOT transient), ‖buf‖_F via
776	    //    per-CTA partials → inv_norm, X=buf·inv_norm, then ns_steps × { A=XXᵀ → AX=A·X
777	    //    → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap }, then the canonical muon_update_step
778	    //    apply (decay·p + neg_lr_scale·orth). The 1D / non-2D weights (biases, LN γ/β)
779	    //    take the AdamW aux tail in P3. The elementwise bodies CALL muon.h
780	    //    (muon_momentum_normalize_step via the phaseA buf body, muon_ns_combine_step,
781	    //    muon_update_step); the matmuls are the cited new device code (the eager path
782	    //    delegates to torch::mm/cuBLAS). Guarded so every other opt is byte-identical
783	    //    (no extra barriers / work).
784	    if constexpr (Opt == OptId::Muon) {
785	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
786	        PrecomputeWorkspace pw{};
787	        pw.muon_X            = muon_base;
788	        pw.muon_AX           = pw.muon_X   + dectc::kDecMuonMaxNumel;
789	        pw.muon_AAX          = pw.muon_AX  + dectc::kDecMuonMaxNumel;
790	        pw.muon_orth         = pw.muon_AAX + dectc::kDecMuonMaxNumel;
791	        pw.muon_A            = pw.muon_orth + dectc::kDecMuonMaxNumel;
792	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows;
793	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
794	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
795	        const int   ns_steps = 5;                 // bindings.cpp default
796	        for (int mi = 0; mi < dectc::kDecNumMuon2D; ++mi) {
797	            const dectc::DecMuon2D M = dectc::kDecMuon2D[mi];
798	            const int rows = M.rows, cols = M.cols;
799	            const int64_t numel = (int64_t)rows * cols;
800	            const int64_t off   = (int64_t)kDecOffsets[M.tidx];
801	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
802	            pw.muon_buf = st.exp_avg + off;
803	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
804	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
805	            bar.sync();
806	            muon_norm_reduce_phaseB(ctx, pw);
807	            bar.sync();
808	            muon_scale_X(numel, pw);
809	            bar.sync();
810	            // NS iterations. After each combine, orth holds the new iterate; swap so
811	            // the next iteration reads it as X. ns_steps swaps → final result is in
812	            // muon_X (the last combine wrote muon_orth, then we swapped → muon_X).
813	            for (int s = 0; s < ns_steps; ++s) {
814	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
815	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
816	                bar.sync();
817	                // AX = A X   (M=rows,N=cols,K=rows).
818	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
819	                bar.sync();
820	                // AAX = A (AX) (M=rows,N=cols,K=rows).
821	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
822	                bar.sync();
823	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
824	                bar.sync();
825	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
826	            }
827	            // Apply Muon: p = decay_factor·p + neg_lr_scale·orth  (muon.h:63-73).
828	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
829	            const float neg_lr_scale = -lr * scale;
830	            const float decay_factor = 1.0f - lr * st.wd;
831	            float* __restrict__ p = params + off;
832	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
833	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
834	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
835	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
836	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
837	        }
838	    }
839	
840	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
841	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
842	    st.lr = lr;
843	    {
844	        __shared__ int task_slot;
845	        TaskQueue q = ctx.queue();
846	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
847	             t = q.next_block(&task_slot)) {
848	            const int n = kDecSizes[t];
849	            const int64_t off = (int64_t)kDecOffsets[t];
850	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
851	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
852	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
853	            if constexpr (Opt == OptId::Muon) {
854	                if (dectc::dec_is_muon_2d(t)) continue;
855	            }
856	            FusedOptState ts = rebase_state<Opt>(st, off);
857	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
858	            //     t == the tensor's flat named_parameters() layer index (the
859	            //     work-steal task id maps 1:1 to kDecOffsets order == the eager
860	            //     enumeration order, so t IS the eager layer index). bc1 must be
861	            //     rebased TOO (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager
862	            //     (~9.6× on the deepest layer); bc2 stays global (β2 not layer-wise).
863	            if constexpr (Opt == OptId::GrokAdamW) {
864	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
865	                ts.beta1 = b1;
866	                ts.bc1   = 1.0f - powf(b1, (float)step);
867	            }
868	            float* __restrict__ p = params + off;
869	            const float* __restrict__ gg = grad + off;
870	            if constexpr (Opt == OptId::Muon) {
871	                // 1D / non-2D weights: the canonical AdamW tail (muon.py:99-125 routes
872	                // non-matrix params to a SEPARATE AdamW group with INDEPENDENT
873	                // hyperparameters — adamw_lr/adamw_betas — NOT the 2D Muon lr/momentum).
874	                // ts.lr/ts.beta1 carry the 2D-group's (lr=0.02, momentum=0.95), so the
875	                // 1D tail MUST instead use the aux_* fields (eager adamw_lr/adamw_betas).
876	                // weight_decay is SHARED across both eager groups (muon.py:122) → ts.wd
877	                // stays. eps is the eager adamw_eps (= ts.eps, mapped by _opt_scalars_from).
878	                // bc1/bc2 are device-computed from aux_beta^step (kept out of the mirror
879	                // to shrink the host ABI; fp32 powf, tol 2e-3 ample). apply_optimizer<Muon>
880	                // would deref st.orth (NS dir, only valid for 2D), so route directly to
881	                // adamw_step with the aux hyperparameters — IDENTICAL to the vit twin.
882	                const float a_bc1 = 1.0f - powf(st.aux_beta1, (float)step);
883	                const float a_bc2 = 1.0f - powf(st.aux_beta2, (float)step);
884	                for (int i = threadIdx.x; i < n; i += blockDim.x)
885	                    algo::adamw_step<float, float>(
886	                        p, ts.exp_avg, ts.exp_avg_sq, gg,
887	                        st.aux_lr, st.aux_beta1, st.aux_beta2, ts.eps, ts.wd,
888	                        a_bc1, a_bc2, (int64_t)i);
889	            } else {
890	                for (int i = threadIdx.x; i < n; i += blockDim.x)
891	                    apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
892	            }
893	        }
894	    }
895	}
